// Reviewer-only diagnostic: legal current public projection, not delivered tests.
import { type BattleSpriteDef, validateBattleSprites, validateActors, validateAssetCatalog, validateCurrentManifestStartup, validateStartWorld } from '@type-pal/content'
import { fsaSource, loadAllAuthorScenes, loadAllProjectMaps, loadCurrentProjectFrom } from '@type-pal/reforge'
import { expect, test } from 'vitest'
import { memoryAuthorDirectory } from './__tests__/author-save-fixture.js'
import { collectEditorDialoguePortraitReferences } from './actor-references.js'
import { assertProjectSaveValid } from './project-diagnostics.js'
import { toEditorState } from './project-io.js'
import { buildBlankProject } from './seed.js'

test('public canonical author files project to typed EditorState portrait references without test casts', async () => {
  const seed = await buildBlankProject('codex-p14-public-projection')
  const png = Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl2bKcAAAAASUVORK5CYII='), c => c.charCodeAt(0))
  const pngHash = [...new Uint8Array(await crypto.subtle.digest('SHA-256', png))].map(b => b.toString(16).padStart(2, '0')).join('')
  const catalog = validateAssetCatalog(seed['assets/index.json'])
  catalog.assets['portrait.probe'] = { kind: 'portrait', path: 'assets/authored/portraits/probe.png', mediaType: 'image/png', bytes: png.byteLength, sha256: pngHash, origin: { kind: 'authored' } }
  seed['assets/index.json'] = catalog
  seed['assets/authored/portraits/probe.png'] = png.buffer.slice(png.byteOffset, png.byteOffset + png.byteLength)
  const actors = validateActors(seed['content/actors.json'])
  actors[0]!.portraits = { default: 'portrait.probe' }
  seed['content/actors.json'] = actors
  const battleSprites = validateBattleSprites(seed['content/battle-sprites.json'], catalog)
  const enemyShape: BattleSpriteDef = { id: 'enemy-probe-shape', label: 'Probe enemy', asset: battleSprites[0]!.asset, profile: { kind: 'enemy', idle: { start: 0, count: 1 }, magic: { start: 1, count: 1 }, attack: { start: 2, count: 1 }, idleTicksPerFrame: 1, actTicksPerFrame: 1 } }
  seed['content/battle-sprites.json'] = [...battleSprites, enemyShape]
  const library = { probe: { name: 'Probe', self: 'none', body: [{ kind: 'dialog', cue: { identity: { kind: 'actor', actor: 'hero', portrait: { kind: 'default', side: 'left' } }, rows: [{ text: 'name.hero' }], slot: 'bottom' } }] } }
  seed['content/shared-scripts.json'] = library
  const { manifest } = validateCurrentManifestStartup(seed['manifest.json'])
  manifest.content.enemies = 'content/enemies.json'
  seed['manifest.json'] = manifest
  seed['content/enemies.json'] = [{ id: 'enemy-probe', name: 'name.hero', battleSprite: 'enemy-probe-shape', yPosOffset: 0, stats: { health: 10, level: 1, exp: 0, cash: 0, attackStrength: 1, magicStrength: 0, defense: 0, dexterity: 1, fleeRate: 0, physicalResistance: 1, poisonResistance: 0, elemResistance: { wind: 0, thunder: 0, water: 0, fire: 0, earth: 0 }, dualMove: false, collectValue: 0 }, ai: { resistanceToSorcery: 0 }, sounds: {}, onDefeated: library.probe!.body }]
  const disk = memoryAuthorDirectory(seed), source = fsaSource(disk.dir)
  const project = await loadCurrentProjectFrom(source)
  const state = toEditorState(project, await loadAllAuthorScenes(project), await loadAllProjectMaps(project), {}, [])
  assertProjectSaveValid(state)
  const refs = collectEditorDialoguePortraitReferences(state)
  console.log('CODEX_PUBLIC_PROJECTION', JSON.stringify({ refs, scriptChunks: state.scriptChunks, source: 'buildBlankProject -> current author file loader -> toEditorState -> assertProjectSaveValid', noTestSideCast: true }))
  expect(refs.filter(r => r.locator?.kind === 'shared-script')).toMatchObject([{ actorId: 'hero', portraitKind: 'default', locator: { kind: 'shared-script', scriptId: 'probe' } }])
  expect(refs.filter(r => r.locator?.kind === 'enemy')).toMatchObject([{ actorId: 'hero', portraitKind: 'default', locator: { kind: 'enemy', enemyId: 'enemy-probe' } }])
  expect(state.scriptChunks).toEqual({})
})

test('public StartWorld validator rejects the delivered empty party id fixture', () => {
  expect(() => validateStartWorld({ party: ['', 'hero'], money: 0, inventory: [] })).toThrow('期望非空角色 id')
})

