import { describe, expect, test } from 'vitest'
import type { MigrationSnapshot } from './migration-baseline.js'
import type { MigrationJson } from './migration-files.js'
import { createMigrationPlan } from './migration-plan.js'
const snapshot = (files: Record<string, MigrationJson>): MigrationSnapshot => ({ files: new Map(Object.entries(files)), managedFiles: new Set(Object.keys(files)) })
describe('Codex plan new-file subaxis', () => {
  test('theirs-only managed non-map file must enter writes', () => {
    const plan = createMigrationPlan(snapshot({}), snapshot({}), snapshot({ 'content/new.json': { added: true } }))
    expect(plan.writes.get('content/new.json')).toEqual({ added: true })
  })
})
